// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        address storedOwner = c.owner();
        vm.prank(caller);
        address returnedFromCaller = c.owner();
        assertTrue(returnedFromCaller == storedOwner);
    }
}
